/*
 * A249591  Lexicographically earliest permutation of the integers such that
 *          a(n+1) shares at least one digit with a(n)-1.
 * https://oeis.org/A249591
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the lexicographically earliest permutation of the
 *            positive integers such that a(n+1) shares at least one digit
 *            with a(n)-1. The sequence is generated by searching
 * Range:     u8 n <= 255, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

/* seq_t and idx_t are supplied by the build; no need to define them here. */

/* ------------  internal data structures  ------------ */

typedef struct {
    idx_t *data;   /* indices of numbers containing the digit */
    size_t size;   /* number of elements stored */
    size_t cap;    /* allocated capacity */
    size_t pos;    /* next candidate position (first unused) */
} bucket_t;

static bucket_t buckets[10];          /* one bucket for each decimal digit */

/* used[i] == 1 if the number i has already been placed in the permutation. */
static uint8_t *used = NULL;
static size_t used_cap = 0;

/* cache of the permutation terms */
static seq_t *cache = NULL;
static size_t cache_len = 0, cache_cap = 0;

/* highest number that has been added to the buckets (and thus to 'used'). */
static idx_t last_generated = 0;

/* ------------  helper routines  ------------ */

/* Ensure that used[] can index up to idx. */
static void ensure_used(idx_t idx)
{
    while ((idx_t)used_cap <= idx) {
        size_t new_cap = used_cap ? used_cap << 1 : 8;
        if (new_cap < (size_t)(idx + 1)) new_cap = (size_t)(idx + 1);
        uint8_t *tmp = (uint8_t *)realloc(used, new_cap * sizeof(uint8_t));
        if (!tmp) abort();
        memset(tmp + used_cap, 0, (new_cap - used_cap) * sizeof(uint8_t));
        used = tmp;
        used_cap = new_cap;
    }
}

/* Append num to all digit buckets. num is assumed unused (used[num]==0). */
static void add_number(idx_t num)
{
    if (num > last_generated) last_generated = num;
    ensure_used(num);
    if (used[num]) abort();          /* number must be unused */
    /* Note: used[num] is 0 here, keep as unused for now */
    bool seen[10] = {0};
    idx_t t = num;
    if (t == 0) seen[0] = 1;
    while (t > 0) {
        int d = (int)(t % 10);
        if (!seen[d]) {
            seen[d] = 1;
            bucket_t *b = &buckets[d];
            if (b->size == b->cap) {
                size_t new_cap = b->cap ? b->cap << 1 : 4;
                idx_t *tmp = (idx_t *)realloc(b->data, new_cap * sizeof(idx_t));
                if (!tmp) abort();
                b->data = tmp;
                b->cap   = new_cap;
            }
            b->data[b->size++] = num;
        }
        t /= 10;
    }
}

/* Ensure cache can hold at least 'needed' entries. */
static void ensure_cache_capacity(size_t needed)
{
    while (cache_cap < needed) {
        size_t new_cap = cache_cap ? cache_cap << 1 : 16;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp) abort();
        cache = tmp;
        cache_cap = new_cap;
    }
}

/* Find the smallest unused number sharing a digit with prev-1. */
static idx_t next_candidate(idx_t prev)
{
    /* digits present in prev-1 */
    bool present[10] = {0};
    idx_t val = prev - 1;
    if (val == 0) present[0] = 1;
    while (val > 0) {
        present[(int)(val % 10)] = 1;
        val /= 10;
    }

    for (;;) {
        idx_t best = (idx_t)-1;   /* sentinel */
        bool found = false;
        for (int d = 0; d < 10; ++d) {
            if (!present[d]) continue;
            bucket_t *b = &buckets[d];
            /* skip used numbers */
            while (b->pos < b->size && used[b->data[b->pos]]) b->pos++;
            if (b->pos < b->size) {
                idx_t cand = b->data[b->pos];
                if (!found || cand < best) {
                    best = cand;
                    found = true;
                }
            }
        }
        if (found) return best;

        /* No candidate found yet – generate the next integer */
        ++last_generated;
        add_number(last_generated);
    }
}

/* ------------  sequence routine  ------------ */

seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* undefined for zero, but avoid UB */

    /* Build the permutation up to term n. */
    while (cache_len < (size_t)n) {
        idx_t next_num;
        if (cache_len == 0) {
            /* First term is 1. */
            next_num = 1;
            add_number(1);
            /* Mark as used. */
            ensure_used(1);
            used[1] = 1;
        } else {
            idx_t prev = (idx_t)cache[cache_len - 1];
            next_num = next_candidate(prev);
            ensure_used(next_num);
            used[next_num] = 1;
        }
        ensure_cache_capacity(cache_len + 1);
        cache[cache_len++] = (seq_t)next_num;
    }

    return cache[n - 1];
}
